export interface MiddlewarePriority {
    request: number;
    response: number;
    error: number;
}

export interface MiddlewareOptions {
    priority?: Partial<MiddlewarePriority>;
}

export declare class Middleware {
    constructor(options?: MiddlewareOptions);
    options: MiddlewareOptions & { priority: MiddlewarePriority };
    static defaultOptions: { priority: MiddlewarePriority };
    static get(middlewares: Middleware[], kind: keyof MiddlewarePriority): Middleware[];
    static run(client: Client, target: unknown, kind: keyof MiddlewarePriority): Promise<unknown>;
    static getDefaultOptions(type: typeof Middleware, options?: Record<string, unknown>): Record<string, unknown>;
    priority(priority: number, kind?: keyof MiddlewarePriority): this;
    request?(request: FetchRequest, client: Client): FetchRequest | Promise<FetchRequest>;
    response?(response: ApiResponse, client: Client): ApiResponse | Promise<ApiResponse>;
    error?(error: unknown, client: Client): unknown | Promise<unknown>;
}

